    methods(Test)
        function testDefaultConstruction(testCase)
            % Test that the default constructor creates an object with the documented defaults.
            transmitter = Transmitter();

            testCase.verifyEqual(transmitter.CarrierFrequency, 6e5);
            testCase.verifyEqual(transmitter.UpsamplingRate, 2e6);
            testCase.verifyEqual(transmitter.UpsamplingMethod, "resample");
        end

        function testConstructionWithCustomProperties(testCase)
            % Test that named arguments are applied during construction.
            transmitter = Transmitter( ...
                CarrierFrequency = 1.2e6, ...
                UpsamplingRate = 4e6, ...
                UpsamplingMethod = "interp");

            testCase.verifyEqual(transmitter.CarrierFrequency, 1.2e6);
            testCase.verifyEqual(transmitter.UpsamplingRate, 4e6);
            testCase.verifyEqual(transmitter.UpsamplingMethod, "interp");
        end

        function testInvalidCarrierFrequencyAssignment(testCase)
            % Test that an invalid carrier frequency is rejected by property validation.
            transmitter = Transmitter();

            testCase.verifyError(@() setInvalidCarrierFrequency(transmitter), ...
                "MATLAB:validators:mustBePositive");
        end

        function testInvalidUpsamplingRateAssignment(testCase)
            % Test that an invalid upsampling rate is rejected by property validation.
            transmitter = Transmitter();

            testCase.verifyError(@() setInvalidUpsamplingRate(transmitter), ...
                "MATLAB:validators:mustBePositive");
        end

        function testNonfiniteUpsamplingRateAssignment(testCase)
            % Test that a nonfinite upsampling rate is rejected by property validation.
            transmitter = Transmitter();

            testCase.verifyError(@() setNonfiniteUpsamplingRate(transmitter), ...
                "MATLAB:validators:mustBeFinite");
        end

        function testInvalidUpsamplingMethodAssignment(testCase)
