            transmitter = Transmitter();

            testCase.verifyError(@() setInvalidUpsamplingMethod(transmitter), ...
                "MATLAB:validators:mustBeMember");
        end

        function testTransmitPreservesMetadataAndTimeSpan(testCase, TransmitMethod)
            % Test that each upsampling branch produces a valid modulated timetable.
            wave = createSilentWave();
            inputSignal = wave.Signal;
            transmitter = Transmitter( ...
                CarrierFrequency = 10, ...
                UpsamplingRate = 2000, ...
                UpsamplingMethod = TransmitMethod);

            transmittedSignal = transmit(transmitter, wave);

            testCase.verifyEqual(height(transmittedSignal), 22);
            testCase.verifyEqual(transmittedSignal.Properties.VariableNames, ...
                inputSignal.Properties.VariableNames);
            testCase.verifyEqual(transmittedSignal.Time(1), inputSignal.Time(1));
            testCase.verifyEqual(transmittedSignal.Time(end), inputSignal.Time(end));
            testCase.verifySize(transmittedSignal.PulsedSineWave, [22 1]);
            testCase.verifyTrue(all(isfinite(transmittedSignal.PulsedSineWave)));
        end

