function setInvalidCarrierFrequency(transmitter)
transmitter.CarrierFrequency = -1;
end

function setInvalidUpsamplingRate(transmitter)
transmitter.UpsamplingRate = 0;
end

function setNonfiniteUpsamplingRate(transmitter)
transmitter.UpsamplingRate = Inf;
end

function setInvalidUpsamplingMethod(transmitter)
transmitter.UpsamplingMethod = "invalid";
end

function wave = createSilentWave()
wave = PulsedSineWave( ...
    Amplitude = 0, ...
    Frequency = 0, ...
    Duration = 0.01, ...
    PulseRate = 1, ...
    Duty = 100, ...
    SampleRate = 1000);
end
